<?php
if (!defined('ABSPATH')) exit;

$beer = get_queried_object();
$beer_id = $beer->ID;

$style    = get_post_meta($beer_id, '_beer_stil', true);
$brewer   = get_post_meta($beer_id, '_beer_brewer', true);
$location = get_post_meta($beer_id, '_beer_location', true);
$ibu      = get_post_meta($beer_id, '_beer_ibu', true);
$abv      = get_post_meta($beer_id, '_beer_abv', true);

$settings  = get_option('beer_festival_settings', []);
$tap_count = isset($settings['tap_count']) ? intval($settings['tap_count']) : 16;

$taps = Tap_Manager::get_all_taps();
$active_tap_ids = [];
$tap_categories = [];
if (!is_wp_error($taps)) {
    foreach ($taps as $tap) {
        if ($tap->active && intval($tap->beer_id) === $beer_id) {
            $active_tap_ids[] = intval($tap->tap_id);
        }
        if (!empty($tap->category)) {
            $tap_categories[intval($tap->tap_id)] = $tap->category;
        }
    }
}

$access_mode = Beer_Festival_Staff_Access::page_mode(); // open | pin | disabled
$current_tap_id = $active_tap_ids ? $active_tap_ids[0] : null;
$is_published = $current_tap_id !== null;
$current_tap_category = $is_published ? ($tap_categories[$current_tap_id] ?? '') : '';
$current_tap_label = $is_published
    ? (($current_tap_category && $current_tap_category !== Beer_Festival_Categories::DEFAULT_CATEGORY)
        ? ($current_tap_id . ' - ' . $current_tap_category)
        : (string) $current_tap_id)
    : '';

